// Follows the cursor until every overdue loan is fetched, so a backlog bigger
// than one page still gets reminders. Each page is signed separately, because
// the signature covers the query string and the timestamp.
const crypto = require('crypto');
const MAX_PAGES = 100;
const secret = $env.CONVEX_INBOUND_SECRET;
if (!secret) throw new Error('CONVEX_INBOUND_SECRET is not set');

const items = [];
let cursor = null;
for (let pages = 0; pages < MAX_PAGES; pages++) {
  const target = '/n8n/overdue-loans' + (cursor === null ? '' : `?cursor=${encodeURIComponent(cursor)}`);
  const timestamp = String(Date.now());
  const signature = crypto.createHmac('sha256', secret)
    .update(`${timestamp}.GET.${target}.`)
    .digest('hex');
  const page = await this.helpers.httpRequest({
    method: 'GET',
    url: `${$env.CONVEX_SITE_URL}${target}`,
    headers: { 'x-lendloop-timestamp': timestamp, 'x-lendloop-signature': signature },
    json: true,
    timeout: 15000,
  });
  for (const loan of page.loans) {
    items.push({ json: { ...loan, reminderDate: page.reminderDate } });
  }
  if (page.isDone) return items;
  cursor = page.continueCursor;
}
throw new Error(`Overdue loans did not finish within ${MAX_PAGES} pages`);

// Mock channel: replace this node with Email, Slack, or similar to send for real.
// A real provider should get idempotencyKey, since a send can succeed while its
// write-back fails, and then the next run sends it again.
const maskEmail = (email) => email.replace(/^(.).*(@.*)$/, '$1***$2');

const { loanId, idempotencyKey, toolName, dueDate, daysOverdue, borrower } = $json;
// Takes the error output below, so this is reported as a failed reminder.
if (!borrower.email) throw new Error('Borrower has no email address');
const reminder = {
  channel: 'mock',
  loanId,
  idempotencyKey,
  to: maskEmail(borrower.email),
  subject: `Please return the ${toolName}`,
  message: `It was due on ${dueDate}, ${daysOverdue} day(s) ago.`,
};
console.log('[LendLoop reminder]', JSON.stringify(reminder));
return { json: reminder };

// Signs the exact string that the next node sends. The write-back doesn't
// depend on the send's output, so a failed send is reported as failed.
const crypto = require('crypto');
const secret = $env.CONVEX_INBOUND_SECRET;
if (!secret) throw new Error('CONVEX_INBOUND_SECRET is not set');

const { loanId, reminderDate } = $('Fetch Overdue Loans').item.json;
const body = JSON.stringify({ loanId, reminderDate, status: $json.status });
const timestamp = String(Date.now());
const signature = crypto.createHmac('sha256', secret)
  .update(`${timestamp}.POST./n8n/reminder-status.${body}`)
  .digest('hex');
return { json: { timestamp, signature, body } };
